const rad = (d: number): number => (d * Math.PI) / 180;
/** The direction the level-3 sun light comes from: the solar direction, never further below the horizon than -0.2 (the
 * twilight sun still lights from a sensible side; the light itself is off below -3 deg). */
function sunLightDir(sp: SunPosition): Vec3 {
  const v = new Vector3(sp.dir[0], Math.max(sp.dir[1], -0.2), sp.dir[2]).normalize();
  return [v.x, v.y, v.z];
}
const isSmall = (p: ScenePart): boolean => p.kind === 'object' && Math.max(p.size[0], p.size[1], p.size[2]) < SMALL_PART_M;
type Role = 'std' | 'floor' | 'glass' | 'object';
const roleOf = (p: ScenePart): Role => (p.kind === 'floor' ? 'floor' : p.color === 'map-glass' ? 'glass' : p.kind === 'object' ? 'object' : 'std');
type Placed = { obj: InstancedMesh | Mesh; index: number; part: ScenePart };

const sameVec = (a: readonly number[], b: readonly number[]): boolean => a.length === b.length && a.every((v, i) => v === b[i]);
const samePolygon = (a: [number, number][] | undefined, b: [number, number][] | undefined): boolean => {
  if (!a || !b) return a === b;
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i][0] !== b[i][0] || a[i][1] !== b[i][1]) return false;
  return true;
};
/** Two parts that realise the same object (everything but a tint's opacity). */
const samePart = (a: ScenePart, b: ScenePart): boolean =>
  a.id === b.id && a.kind === b.kind && a.shape === b.shape && a.color === b.color && a.group === b.group && a.level_id === b.level_id && a.text === b.text && sameVec(a.position, b.position) && sameVec(a.size, b.size) && sameVec(a.rotation, b.rotation) && samePolygon(a.polygon, b.polygon) && (a.opacity === b.opacity || a.kind === 'tint');

/** A description that differs from another only in the opacity of its tints (a presence fade step): the same parts
 * in the same order, the same levels - the realised graph can stay and the tint materials take the new values. */
export function tintOnlyChange(from: SceneDescription, to: SceneDescription): boolean {
  if (from === to || from.parts.length !== to.parts.length || from.levels.length !== to.levels.length) return false;
  if (from.size[0] !== to.size[0] || from.size[1] !== to.size[1]) return false;
  for (let i = 0; i < from.levels.length; i++) {
    const a = from.levels[i];
    const b = to.levels[i];
    if (a.id !== b.id || a.elevation_m !== b.elevation_m || a.ceiling_height_m !== b.ceiling_height_m) return false;
  }
  let differs = false;
  for (let i = 0; i < from.parts.length; i++) {
    const a = from.parts[i];
    const b = to.parts[i];
    if (!samePart(a, b)) return false;
    if (a.opacity !== b.opacity) differs = true;
  }
  return differs;
}

/** Two DOM-label parts (a temperature chip, an entity pill) that draw the same label. */
const sameLabel = (a: ScenePart, b: ScenePart): boolean =>
  a.text === b.text && a.color === b.color && a.opacity === b.opacity && sameVec(a.position, b.position) && sameVec(a.size, b.size) && a.userData.id === b.userData.id && a.userData.kind === b.userData.kind;

/**
 * PERF3D-295: a description that differs from another only in what the scene graph never draws or draws in place - the
 * opacity of its tints (a presence fade step, as tintOnlyChange) and the DOM labels (DOM_LABEL_KINDS: a temperature chip's
 * reading, an entity pill's text or state colour - the element lays them out over the canvas, three realises nothing for
 * them). The same parts in the same order otherwise, the same levels and size; with a label changed, the realistic part must
 * be the same as well (level 3 reads its lamps and rooms from it). A home's meters push a new reading every few seconds: each
 * used to rebuild the whole graph, the shadow map and the cutaway.
 */
export function liveOnlyChange(from: SceneDescription, to: SceneDescription): boolean {
  if (from === to || from.parts.length !== to.parts.length || from.levels.length !== to.levels.length) return false;
  if (from.size[0] !== to.size[0] || from.size[1] !== to.size[1]) return false;
  for (let i = 0; i < from.levels.length; i++) {
    const a = from.levels[i];
    const b = to.levels[i];
    if (a.id !== b.id || a.elevation_m !== b.elevation_m || a.ceiling_height_m !== b.ceiling_height_m) return false;
  }
  let differs = false;
  let labels = false;
  for (let i = 0; i < from.parts.length; i++) {
    const a = from.parts[i];
    const b = to.parts[i];
    if (DOM_LABEL_KINDS.has(a.kind) && a.kind === b.kind && a.id === b.id && a.level_id === b.level_id && a.shape === b.shape) {
      if (!sameLabel(a, b)) differs = labels = true;
      continue;
    }
    if (!samePart(a, b)) return false;
    if (a.opacity !== b.opacity) differs = true;
  }
  if (labels && (from.real || to.real) && JSON.stringify(from.real ?? null) !== JSON.stringify(to.real ?? null)) return false;
  return differs;
}

/** The twelve edges of the unit box as line segments (an outline without EdgesGeometry). */
function unitBoxEdges(): BufferGeometry {
  const c = [-0.5, 0.5];
  const pts: number[] = [];
  for (const a of c) for (const b of c) {
    pts.push(-0.5, a, b, 0.5, a, b); // along x
    pts.push(a, -0.5, b, a, 0.5, b); // along y
    pts.push(a, b, -0.5, a, b, 0.5); // along z
  }
  const g = new BufferGeometry();
  g.setAttribute('position', new Float32BufferAttribute(pts, 3));
  return g;
}

/** The contact-occlusion texture: black, opaque-ish in the middle, fading to the edge along a rounded-box falloff (an
 * instance stretched over a long wall keeps a soft band at its ends and a tight one along its faces). */
function occlusionTexture(): CanvasTexture {
  const n = 64;
  const canvas = document.createElement('canvas');
  canvas.width = n;
  canvas.height = n;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    const img = ctx.createImageData(n, n);
    for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
      const u = Math.abs((x + 0.5) / n - 0.5) * 2;
      const v = Math.abs((y + 0.5) / n - 0.5) * 2;
      const d = Math.max(u, v);
      const t = Math.min(1, Math.max(0, (d - 0.5) / 0.5));
      const a = (1 - t * t * (3 - 2 * t)) * 0.42;
      const i = (y * n + x) * 4;
      img.data[i + 3] = Math.round(a * 255);
    }
    ctx.putImageData(img, 0, 0);
  }
  const texture = new CanvasTexture(canvas);
  texture.colorSpace = SRGBColorSpace;
  return texture;
}

/**
 * A vertical prism over a floor polygon (x, z relative to the part's origin), from y = 0 to y = h. Tolerates what the
 * builder can hand over: a closing duplicate, repeated points (a camera inside a wall gives zero-length fan edges), a
 * full-circle cone without its origin, a degenerate (zero-area) ring - that one yields null.
 */
export function prismGeometry(polygon: [number, number][], h: number): BufferGeometry | null {
  const ring: [number, number][] = [];
  for (const q of polygon) {
    const last = ring[ring.length - 1];
    if (!last || Math.hypot(q[0] - last[0], q[1] - last[1]) > 1e-6) ring.push(q);
  }
  while (ring.length > 1 && Math.hypot(ring[0][0] - ring[ring.length - 1][0], ring[0][1] - ring[ring.length - 1][1]) <= 1e-6) ring.pop();
  if (ring.length < 3 || !(h > 0)) return null;
  let area = 0;
  for (let i = 0; i < ring.length; i++) {
    const a = ring[i];
    const b = ring[(i + 1) % ring.length];
    area += a[0] * b[1] - b[0] * a[1];
  }
  if (Math.abs(area) < 1e-8) return null;
  const tris = ShapeUtils.triangulateShape(ring.map(([x, z]) => new Vector2(x, z)), []);
  const pos: number[] = [];
  for (const [i, j, k] of tris) {
    const [a, b, c] = [ring[i], ring[j], ring[k]];
    if (Math.abs((b[0] - a[0]) * (c[1] - a[1]) - (c[0] - a[0]) * (b[1] - a[1])) < 1e-10) continue; // a zero-area sliver
    pos.push(a[0], h, a[1], b[0], h, b[1], c[0], h, c[1]); // the top cap
    pos.push(a[0], 0, a[1], c[0], 0, c[1], b[0], 0, b[1]); // the bottom cap, reversed
  }
  for (let i = 0; i < ring.length; i++) {
    const a = ring[i];
    const b = ring[(i + 1) % ring.length];
    pos.push(a[0], 0, a[1], b[0], 0, b[1], b[0], h, b[1], a[0], 0, a[1], b[0], h, b[1], a[0], h, a[1]);
  }
  const g = new BufferGeometry();
  g.setAttribute('position', new Float32BufferAttribute(pos, 3));
  g.computeVertexNormals();
  return g;
}

